#pragma once
#include "FaceBranch.h"
#include "../film_rail_tendon/ControlProfile.h"
namespace regrip_three_resume {
struct EdgeOwner {unsigned finger,sourceTriangle;std::array<unsigned,2>nodes;};
inline regrip_collocation::RowGeometry edgeGeometry(const SharedFilmSystem&s,const Eigen::VectorXd&q,const std::vector<EdgeOwner>&owners){
 const unsigned n=q.size(),nf=s.shared.nf,nb=3*nf;regrip_collocation::RowGeometry out{Eigen::VectorXd(owners.size()),Eigen::MatrixXd::Zero(owners.size(),n),std::vector<Eigen::MatrixXd>(owners.size(),Eigen::MatrixXd::Zero(n,n))};
 for(unsigned k=0;k<owners.size();++k){const auto&o=owners[k];const auto&sys=s.shared.films[o.finger];auto local=s.local(q,o.finger);auto rest=sys.film.model.rest();std::vector<Point>relative;for(unsigned node:o.nodes)relative.push_back(sub(add(rest[node],local.q[node]),point(local.body.center)));auto e=ClosestPrimitive::evaluate(relative,{0,0,0},s.layout.bufferRadius);if(e.feature!=3)throw std::runtime_error("edge endpoint/vertex event requires separate branch");Eigen::MatrixXd D=Eigen::MatrixXd::Zero(6,n);for(unsigned a=0;a<6;++a){unsigned ga=3*o.nodes[a/3]+a%3;int index=sys.film.index[ga];if(index>=0)D(a,o.finger*nf+index)=sys.film.weight[ga];for(unsigned d=0;d<3;++d)D(a,nb+d)=-s.layout.mount[o.finger].R(d,a%3);}Eigen::VectorXd g(6);Eigen::MatrixXd H(6,6);for(unsigned a=0;a<6;++a){g(a)=e.gap.g[a];for(unsigned b=0;b<6;++b)H(a,b)=e.gap.h[regrip_film::N*a+b];}out.gap(k)=e.gap.v;out.J.row(k)=g.transpose()*D;out.H[k]=D.transpose()*H*D;}return out;
}
struct FaceEdgeTransfer {regrip_collocation::RowsResult pre,post;std::vector<ContactOwner>faces;std::vector<EdgeOwner>edges;double eventH=0,bracketWidth=0,minimumGap=0,minimumFaceParameter=0,minimumIndependentGap=0,Jcontinuity=0,edgeNormalVelocity=0;unsigned evaluations=0;};
// Bounded symmetric face-interior -> shared material-edge transition. No
// velocity jump/impact,normal clamp,position projection or contact compliance.
// Topological aliases remain included in ALL-triangle physical clearance.
inline FaceEdgeTransfer faceEdgeTransfer(const SharedFilmSystem&s,const Eigen::VectorXd&q,const Eigen::VectorXd&v,double time,double h){
 FaceEdgeTransfer out;for(unsigned f=0;f<3;++f){auto r=s.selected(q,f);if(r.feature!=6)throw std::runtime_error("face-edge initial state not a smooth face");out.faces.push_back({f,r.triangle,6});}
 auto force=[&](const auto&x,double t){return s.force(x,regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension);};auto advance=[&](double interval){return regrip_collocation::persistentRows(s.shared.M,2,q,v,time,interval,force,[&](const auto&x){return faceBranchGeometry(s,x,out.faces);});};
 auto independentGap=[&](const Eigen::VectorXd&x){double gap=1e100;for(unsigned f=0;f<3;++f){auto state=s.local(x,f);const auto&sys=s.shared.films[f];const auto&active=sys.triangles[out.faces[f].triangle];for(unsigned k=0;k<sys.triangles.size();++k)if(k!=out.faces[f].triangle){auto e=sys.primitive(state,k);std::vector<unsigned>support;if(e.feature<3)support={sys.triangles[k][e.feature]};else if(e.feature==3)support={sys.triangles[k][0],sys.triangles[k][1]};else if(e.feature==4)support={sys.triangles[k][0],sys.triangles[k][2]};else if(e.feature==5)support={sys.triangles[k][1],sys.triangles[k][2]};else support={sys.triangles[k][0],sys.triangles[k][1],sys.triangles[k][2]};bool alias=true;for(unsigned node:support)if(std::find(active.begin(),active.end(),node)==active.end())alias=false;if(!alias)gap=std::min(gap,e.gap.v);}}return gap;};
 if(independentGap(q)<=0||minimumFaceParameter(s,q,out.faces)<=0)throw std::runtime_error("face-edge initial independent/parameter separation fails");auto predicted=advance(h);++out.evaluations;if(independentGap(predicted.q)>0&&minimumFaceParameter(s,predicted.q,out.faces)>0)throw std::runtime_error("face-edge bracket not signed");double lo=0,hi=h;
 for(unsigned i=0;i<48&&hi-lo>1e-13;++i){double mid=(lo+hi)/2;auto r=advance(mid);++out.evaluations;if(independentGap(r.q)>0&&minimumFaceParameter(s,r.q,out.faces)>0)lo=mid;else hi=mid;}
 out.eventH=(lo+hi)/2;out.bracketWidth=hi-lo;out.pre=advance(out.eventH);++out.evaluations;out.minimumFaceParameter=minimumFaceParameter(s,out.pre.q,out.faces);out.minimumIndependentGap=independentGap(out.pre.q);if(std::abs(out.minimumFaceParameter)>1e-10||out.minimumIndependentGap<=0)throw std::runtime_error("independent surface birth/coincident event before face-edge boundary");
 for(unsigned f=0;f<3;++f){auto b=faceBranch(relativeTriangle(s,out.pre.q,out.faces[f]),s.layout.bufferRadius).barycentric;unsigned opposite=std::min_element(b.begin(),b.end())-b.begin();if(std::abs(b[opposite])>1e-10)throw std::runtime_error("asynchronous feature roots require mixed owner step");const auto&tri=s.shared.films[f].triangles[out.faces[f].triangle];EdgeOwner e{f,out.faces[f].triangle,{0,0}};unsigned count=0;for(unsigned j=0;j<3;++j)if(j!=opposite)e.nodes[count++]=tri[j];out.edges.push_back(e);}
 auto face=faceBranchGeometry(s,out.pre.q,out.faces),edge=edgeGeometry(s,out.pre.q,out.edges);out.Jcontinuity=(face.J-edge.J).cwiseAbs().maxCoeff();out.edgeNormalVelocity=(edge.J*out.pre.v).cwiseAbs().maxCoeff();if(out.Jcontinuity>1e-8||out.edgeNormalVelocity>1e-10||edge.gap.cwiseAbs().maxCoeff()>1e-10)throw std::runtime_error("face-edge C1/normal velocity matching failed;NO velocity reset");
 out.post=regrip_collocation::persistentRows(s.shared.M,2,out.pre.q,out.pre.v,time+out.eventH,h-out.eventH,force,[&](const auto&x){return edgeGeometry(s,x,out.edges);});out.minimumGap=s.clearance(out.post.q);for(const auto&stage:out.pre.stages)out.minimumGap=std::min(out.minimumGap,s.clearance(stage.q));for(const auto&stage:out.post.stages)out.minimumGap=std::min(out.minimumGap,s.clearance(stage.q));if(out.minimumGap< -1e-10)throw std::runtime_error("face-edge whole-stage clearance failed");return out;
}
}
